	BatchID       *string             `json:"batch_id"`
	Changes       *[]changeEntryInput `json:"changes"`
	GateStatus    *string             `json:"gate_status"`
	RollbackPoint *string             `json:"rollback_point"`
}

type changeEntryView struct {
