			bound, err := parseTimeBound(raw, true)
			if err != nil {
				fail(c, http.StatusUnprocessableEntity, store.CodeReleaseValidationV1,
					"recorded_to must be an RFC3339 timestamp or a YYYY-MM-DD date")
				return
			}
			filter.To = bound
		}

