			Environment: filter.Environment,
			Version:     filter.Version,
			BatchID:     filter.BatchID,
			Category:    filter.Category,
			Title:       filter.Title,
			GateStatus:  filter.GateStatus,
			From:        filter.From,
			To:          filter.To,
