					RecordedAt: last.RecordedAt,
					RecordID:   last.RecordID,
					Sequence:   last.Entry.Sequence,
					Title:      last.Entry.Title,
				},
			})
			items = items[:limit]
		}
		views := make([]changeEntryItemView, 0, len(items))
		for _, item := range items {
